#define DIRECT_J_NO_MAIN
#include "../../j_integral_methods/native/direct_j.cpp"
#include "triangular.hpp"
ZR as_z(const RF&x){return ZR(univariate(x.n),univariate(x.d));}
ZR at_z(const RF&x,U a){auto p=specialize(x,a);return ZR(p.first,p.second);}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("audit_fbi INPUT REPORT [point]");json cfg;{std::ifstream f(argv[1]);f>>cfg;}prime=cfg["prime"];nmod_init(&mod,prime);nmod_mpoly_ctx_init(mc,2,ORD_LEX,prime);std::string point=argc>3?argv[3]:"17";U a=constant(readr(point));auto start=Clock::now();cfg["specialize_t"]=point;cfg["targets"]=json::array();NativeFamily value(cfg);RMat At,Az;std::map<std::string,RRow>targets;value.model(At,Az,targets);int r=value.rank;
 json jet_cfg=cfg;jet_cfg.erase("specialize_t");jet_cfg["fbi_corner_aliases"]=json::array();for(auto&[x,y]:value.corner_aliases)jet_cfg["fbi_corner_aliases"].push_back({x,y});first_jet_center=a;first_jet_mode=true;NativeFamily jet(jet_cfg);RMat Bt,Bz;jet.model(Bt,Bz,targets);
 std::vector<std::vector<ZR>>T(r),Z(r),dTz(r),dZt(r);for(int i=0;i<r;++i)for(int j=0;j<r;++j){T[i].push_back(as_z(At[i][j]));Z[i].push_back(as_z(Az[i][j]));dTz[i].push_back(as_z(At[i][j].diff(1)));dZt[i].push_back(at_z(Bz[i][j].diff(0),a));}first_jet_mode=false;json failures=json::array();long long checks=0;
 for(int i=0;i<r;++i){for(int j=i;j<r;++j){ZR f=dTz[i][j]-dZt[i][j];for(int k=i;k<=j;++k){if(!T[i][k].zero()&&!Z[k][j].zero())f=f+T[i][k]*Z[k][j];if(!Z[i][k].zero()&&!T[k][j].zero())f=f-Z[i][k]*T[k][j];}++checks;if(!f.zero())failures.push_back({{"row",value.masters[i]},{"column",value.masters[j]},{"numerator",polyjson(f.n)},{"denominator",polyjson(f.d)}});}if(i%20==0)std::cerr<<"flatness row "<<i<<"/"<<r<<" elapsed="<<seconds(start)<<"s\n";}
 json aliases=json::array();for(auto&[x,y]:value.corner_aliases)if(x!=y)aliases.push_back({x,y});json out={{"point",point},{"prime",prime},{"rank",r},{"aliases",aliases},{"flatness_checks",checks},{"all_pass",failures.empty()},{"failures",failures},{"total_seconds",seconds(start)}};std::filesystem::path path(argv[2]);if(!path.parent_path().empty())std::filesystem::create_directories(path.parent_path());std::ofstream f(path);f<<out.dump(2);std::cout<<"FBI flatness failures="<<failures.size()<<" rank="<<r<<" seconds="<<seconds(start)<<"\n";return failures.empty()?0:2;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
